import json

with open('./data.json', 'r') as f:
    data = json.load(f)

target_timestamp = "2025-05-29T19:00:25.331Z"

def find_by_timestamp(obj, target):
    if isinstance(obj, dict):
        if obj.get('timestamp') == target:
            return obj
        for v in obj.values():
            result = find_by_timestamp(v, target)
            if result:
                return result
    elif isinstance(obj, list):
        for item in obj:
            result = find_by_timestamp(item, target)
            if result:
                return result
    return None

result = find_by_timestamp(data, target_timestamp)
print(json.dumps(result, indent=2))
